// Reveal backprop layer
tl.to('#backprop-arrows', { opacity: 1, duration: 0.4 }, startTime);

// Shift stroke-dashoffset backward smoothly
tl.fromTo('#backprop-arrows line',
  { strokeDashoffset: 0 },
  { strokeDashoffset: -60, duration: 3.0, ease: 'none' },
  startTime + 0.1
);
